// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount > 1);
        address actor = address(0xABCD);

        // First deposit: gives the actor a nonzero accumulated balance.
        vm.deal(actor, 1 ether + uint256(amount) * 2);
        vm.prank(actor);
        c.Put{value: 1 ether}(0);

        // Second deposit of the fuzzed amount.
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: the last logged value for a Put always equals the amount sent in that Put.
        (, , uint val, ) = c.LogFile().History(c.LogFile().History_length() - 1);
        assertTrue(val == uint256(amount), "logged value must equal deposited amount");
    }
}

