pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount2 > 0);
        // two deposits by the same actor through Put
        vm.deal(actor, uint256(amount1) + uint256(amount2));
        if (amount1 > 0) {
            vm.prank(actor);
            c.Put{value: amount1}(0);
        }
        vm.prank(actor);
        c.Put{value: amount2}(0);

        // general rule: the newest log entry records exactly the amount of the most
        // recent deposit (Val == msg.value of the last Put), not the running balance.
        (, , uint val, ) = c.LogFile().History(c.LogFile().History_length() - 1);
        assertTrue(val == uint256(amount2));
    }
}

