pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 a1 = bound(uint256(amount1), 1, 1 ether);
        uint256 a2 = bound(uint256(amount2), 1, 1 ether);

        vm.deal(actor, a1 + a2);
        vm.prank(actor);
        c.Put{value: a1}(0);
        vm.prank(actor);
        c.Put{value: a2}(0);

        uint256 sum = 0;
        uint256 len = lg.History_length();
        for (uint256 i = 0; i < len; i++) {
            (, , uint val, ) = lg.History(i);
            sum += val;
        }
        assertTrue(sum == address(c).balance);
    }
}

