pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        Log l = new Log();
        lg = l;
        c = new C(address(new Log()));
        // replace with the log we can read
        // (deploy a fresh C attached to l)
        c = new C(address(l));
    }

    function testFuzz_property(uint256 amountA, uint256 amountB) public {
        uint256 a = bound(amountA, 1, 1e30);
        uint256 b = bound(amountB, 1, 1e30);
        vm.assume(a + b > a && a + b > b); // no overflow
        address actor = address(0xABEE);
        vm.deal(actor, a + b);

        vm.prank(actor);
        c.Put{value: a}(0);
        vm.prank(actor);
        c.Put{value: b}(0);

        (, , uint256 v1, ) = lg.History(0);
        (, , uint256 v2, ) = lg.History(1);
        uint256 bal = c.Acc(actor).balance;

        // General rule: the value logged by the second Put is the deposited amount b,
        // so it must NOT equal the sender's accumulated balance unless the deposit
        // itself constitutes the whole balance (b == a + b). The mutant logs the
        // accumulated balance a+b, violating this whenever b != a+b.
        assertTrue(v2 != bal || v2 == b);
    }
}

