pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 seedAmount, uint256 amount, uint256 unlockTime) public {
        address actor = address(0xA11CE);
        seedAmount = bound(seedAmount, 1, 100 ether);
        amount = bound(amount, 1, 100 ether);
        unlockTime = bound(unlockTime, 0, 2**64);

        vm.deal(actor, seedAmount + amount);
        vm.prank(actor);
        c.Put{value: seedAmount}(unlockTime);

        (, uint256 balBefore) = c.Acc(actor);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (, uint256 balAfter) = c.Acc(actor);
        (,, uint256 lastVal,) = c.History(c.History.length() - 1);

        assertTrue(lastVal == balAfter - balBefore);
    }
}

