pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint64 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        uint256 amt = bound(uint256(amount), 1, type(uint64).max);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(unlockTime);

        // The Log was deployed immediately before c; locate it by scanning nearby addresses.
        bool found = false;
        address sender = address(0);
        for (uint256 i = 1; i <= 5 && !found; i++) {
            address cand = address(uint160(uint256(address(c)) - i));
            (bool ok, bytes memory ret) = cand.call(
                abi.encodeWithSelector(Log.History.selector, 0)
            );
            if (ok && ret.length == 128) {
                (sender, , , ) = abi.decode(ret, (address, string, uint256, uint256));
                found = true;
            }
        }
        assertTrue(found && sender == actor);
    }
}

